#include <bits/stdc++.h>
using namespace std;

const int MAX_T = 10000;
const int MAX_N = 2e5;

vector<int> a, b;
vector<int> sorted_a;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n, k;
        cin >> n >> k;
        a.resize(n);
        b.resize(n);
        for (int i = 0; i < n; ++i) {
            cin >> a[i];
        }
        for (int i = 0; i < n; ++i) {
            cin >> b[i];
        }

        // Precompute sorted_a
        sorted_a = a;
        sort(sorted_a.begin(), sorted_a.end());

        int median_pos = (n - 1) / 2;
        int initial_median = sorted_a[median_pos];

        int max_score = 0;

        // Try each element as the one to increase
        for (int i = 0; i < n; ++i) {
            int x = min(k, b[i]);
            k -= x;
            if (k < 0) break;

            // Create new array after increasing a[i] by x
            vector<int> s = a;
            s[i] += x;
            sort(s.begin(), s.end());

            int new_median = s[median_pos];
            int score = (a[i] + x) + new_median;
            max_score = max(max_score, score);
        }

        cout << max_score << "\n";
    }

    return 0;
}
